package cn.edu.lostfound.controller;
import cn.edu.lostfound.dto.*;import cn.edu.lostfound.entity.Item;import cn.edu.lostfound.security.UserContext;import cn.edu.lostfound.service.ItemService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/admin") public class AdminController {private final ItemService service;public AdminController(ItemService s){service=s;}private void check(){if(!UserContext.admin())throw new SecurityException("仅管理员可操作");}@GetMapping("/items/pending")public ApiResponse<List<Item>> pending(){check();return ApiResponse.ok(service.pending());}@PutMapping("/items/{id}/review")public ApiResponse<Item> review(@PathVariable Long id,@Valid @RequestBody ItemDtos.Review r){check();return ApiResponse.ok(service.review(id,r.status()));}}
